let worldRegions,beliefs={},polityStore,polityManifest,polityCatalog=[],polityProfiles={},pendingEntity=null,modalSource=null;
let territoryStore,territoryManifest,editorial,territoryData=null,displayAreas=[],selectedArea=null,areaRequest=0,religionFilter='all',showPlaces=false,currentMapYear=null,pendingAreaId=null;
