function persist(){const p=new URLSearchParams({year:String(year),mode,culture:selected||'',lang:getLanguage()});if(selectedArea)p.set('area',selectedArea.id);if(religionFilter!=='all')p.set('religion',religionFilter);history.replaceState(null,'','#'+p);try{localStorage.setItem('chronos-state-v1',JSON.stringify({year,mode,selected}));}catch{}}
function toast(msg){$('#toast').textContent=tx(msg);$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function setPanel(name,focus=true){const previous=panel;if(name&&!previous)returnFocus=document.activeElement?.tagName==='BODY'?$('#globe'):document.activeElement;panel=name;$('#explorerPanel').hidden=name!=='explorer';$('#detailPanel').hidden=name!=='detail';$('#searchToggle').setAttribute('aria-expanded',String(name==='explorer'));globe?.setPanel(name);if(name){if(focus)requestAnimationFrame(()=>{if(panel===name)(name==='explorer'?$('#search'):$('#detailPanel [data-close-panel]')).focus({preventScroll:true});});}else if(previous&&focus){(returnFocus?.isConnected?returnFocus:$('#globe')).focus({preventScroll:true});}}
function setImmersive(active){document.body.classList.toggle('focus-mode',active);$('#exitFocus').hidden=!active;$('#focusMode').setAttribute('aria-pressed',String(active));$('#focusMode').setAttribute('aria-label',tx(active?'Выключить режим погружения':'Включить режим погружения'));if(active){setPanel(null,false);toggleYear(false);toggleLegend(false);$('#globe').focus({preventScroll:true});}else $('#focusMode').focus({preventScroll:true});}
function selectCulture(id,focus=true){selectedArea=null;const c=data.cultures.find(c=>c.id===id);if(!c)return;stop();setSpin(false);selected=id;if(year<c.start||year>c.end){year=Math.max(c.start,Math.min(c.end,year));toast(`Переход: ${formatYear(year)}`);}if(document.body.classList.contains('focus-mode'))setImmersive(false);render();toggleYear(false);toggleLegend(false);setPanel('detail');if(focus)globe.focus(c.coordinates);}
function setYear(y){selectedArea=null;year=y;if(!current().some(c=>c.id===selected))selected=chooseCurrent();render();}
function setMode(m){selectedArea=null;mode=m;render();toast(modeNames[m]);}
function cultureRows(rows){const expanded=new Set($$('.region-group[open]').map(g=>g.dataset.region));const initial=!$('#cultureList').children.length;return Object.entries(regionColors).map(([r,col])=>{const cs=rows.filter(c=>c.region===r);if(!cs.length)return '';return `<details class="region-group" data-region="${r}" ${initial||expanded.has(r)||q?'open':''}><summary><span class="swatch" style="background:${col}"></span>${r}<span class="group-count">${cs.length}</span>${icon('chevron')}</summary><div>${cs.map(c=>`<button class="culture-row ${c.id===selected?'selected':''}" data-culture="${c.id}" aria-pressed="${c.id===selected}"><span><strong>${esc(c.name)}</strong><small>${c.start<=year&&year<=c.end?esc(c.kind):period(c)+' · перейти'}</small></span><span class="row-arrow">${icon('arrow')}</span></button>`).join('')}</div></details>`;}).join('');}
function render(){const list=visible(),allCurrent=current();if(selected&&!allCurrent.some(c=>c.id===selected))selected=null;
 $('#worldDate').innerHTML=html(`${Math.abs(year).toLocaleString(getLanguage()==='en'?'en-US':'ru-RU')} <small>${year<0?'до н. э.':'н. э.'}</small>`);$('#dateJump').setAttribute('aria-label',tx(`${formatYear(year)}. Выбрать другой год`));
 let epoch=epochs[0];for(const e of epochs)if(year>=e.start)epoch=e;$('#epochLabel').textContent=tx(epoch.name.toUpperCase());$('#dockEpoch').textContent=tx(epoch.name);
 const pos=yearToPosition(year);$('#timeRange').value=pos;$('#timeRange').style.setProperty('--progress',`${pos/10}%`);$('#timeRange').setAttribute('aria-valuetext',tx(formatYear(year)));$('#yearInput').value=Math.abs(year);$('#era').value=year<0?'bce':'ce';$('#relationType').hidden=mode!=='relations';
 $('#activeCount').textContent=tx(`${list.length} ${list.length===1?'место':'мест'}`);$('#modeCaption').textContent=tx(modeNames[mode]);
 $$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode);});
 const rows=q?data.cultures.filter(c=>matches(c,q)&&(region==='all'||c.region===region)):list;$('#count').textContent=tx(rows.length);$('#listCaption').textContent=tx(q?'РЕЗУЛЬТАТЫ ВО ВСЕХ ЭПОХАХ':'В ВЫБРАННОМ ГОДУ');
 $('#cultureList').innerHTML=html(rows.length?cultureRows(rows):`<div class="empty">${q?'Пока не нашли такую историю. Попробуйте другое название.':'Для этого времени и региона записи ещё не добавлены.'}<button id="clearFilters">Сбросить фильтры</button></div>`);
 const displayed=mode==='relations'?list.filter(c=>links().some(r=>r.from===c.id||r.to===c.id)):list;
 globe.setData(displayed,links(),mode,selected,color);
 if(mode==='religions'){const rels=[...new Set(list.flatMap(c=>c.religions))];$('#legend').innerHTML=html(rels.map(id=>`<span><i style="background:${data.religions[id].color}"></i>${esc(data.religions[id].name)}</span>`).join(''));}else if(mode==='relations')$('#legend').innerHTML=html('<span><i style="background:#e3eaa4"></i>Торговля и обмен →</span><span><i style="background:#edac83"></i>Колониальная зависимость ⇢</span>');else $('#legend').innerHTML=html(Object.entries(regionColors).filter(([r])=>list.some(c=>c.region===r)).map(([r,col])=>`<span><i style="background:${col}"></i>${r}</span>`).join(''));
 const c=list.find(c=>c.id===selected)||list[0];$('#sceneKicker').textContent=tx(mode==='relations'?'МИР, СОЕДИНЁННЫЙ СВЯЗЯМИ':mode==='religions'?'КАК ЧЕЛОВЕК ОБЪЯСНЯЛ МИР':'СЛЕДЫ ОДНОЙ ЭПОХИ');$('#sceneCaption').textContent=tx(c?c.name:'История здесь ещё ждёт своего исследователя.');$('#discover').dataset.culture=c?.id||'';$('#discover').disabled=!c;
 renderDetail();persist();mapPromise=syncAreas();
}
function chapter(id,title,ico,body,open=false){return `<details class="chapter" data-chapter="${id}" ${open?'open':''}><summary>${icon(ico)}<span>${esc(title)}</span>${icon('chevron','chevron')}</summary><div class="chapter-body">${body}</div></details>`;}
function renderDetail(){if(selectedArea){renderAreaDetail();return;}const c=data.cultures.find(c=>c.id===selected);const key=selected+':'+mode;const open=detailKey===key?new Set($$('#detail details[open]').map(d=>d.dataset.chapter)):new Set();detailKey=key;
 if(!c){$('#detail').innerHTML=html(`<div class="detail-top">НЕИССЛЕДОВАННЫЙ УЧАСТОК</div><h2>История ещё не добавлена</h2><p class="summary">В выбранном году база пока не содержит записей. Здесь тоже жили люди — нам ещё предстоит рассказать об их мире.</p><button class="primary" data-story="pyramids">Начать с эпохи пирамид ${icon('arrow')}</button><button class="secondary" data-about>О покрытии базы</button>`);return;}
 let content='';if(mode==='cultures'){
  const rulers=c.rulers.filter(r=>r.start<=year&&year<=r.end),events=[...c.events].filter(e=>e.year<=year).sort((a,b)=>b.year-a.year);
  content=`<p class="summary">${esc(c.summary)}</p>`;
  content+=chapter('society','Как было устроено общество','cultures',`<dl><dt>Власть</dt><dd>${esc(c.government)}</dd><dt>Люди и повседневность</dt><dd>${esc(c.society)}</dd><dt>Правитель в ${formatYear(year)}</dt><dd>${rulers.length?rulers.map(r=>esc(r.name)).join(', '):'В проверенной базе пока не указан'}</dd></dl>`,open.has('society'));
  content+=chapter('economy','Чем жили и что производили','relations',`<p>${esc(c.economy)}</p>`,open.has('economy'));
  content+=chapter('beliefs','Во что верили','religions',c.religions.map(id=>`<p><strong style="color:${data.religions[id].color}">${esc(data.religions[id].name)}</strong><br>${esc(data.religions[id].summary)}</p>`).join(''),open.has('beliefs'));
  if(events.length)content+=chapter('events','События к выбранному году','time',events.map(e=>`<div class="event"><strong>${formatYear(e.year)}</strong><p>${esc(e.text)}</p></div>`).join(''),open.has('events'));
 }else if(mode==='religions'){
  content='<p class="summary">Как человек объяснял мир, смерть, власть и своё место среди других. Откройте традицию, чтобы прочитать её историю.</p>';
  content+=c.religions.map(id=>{const r=data.religions[id];return chapter('rel-'+id,r.name,'religions',`<p>${esc(r.summary)}</p><dl><dt>Формирование</dt><dd>${esc(r.origin)}</dd></dl>${sourceLinks(r.sources)}`,open.has('rel-'+id));}).join('');
  content+='<p class="uncertainty">Традиции могли сосуществовать. Цвет не обозначает долю верующих или однородность общества.</p>';
 }else{
  const rels=links().filter(r=>r.from===c.id||r.to===c.id);content='<p class="summary">Следуйте за вещами и людьми: что обменивали, кто получал выгоду, кому доставались издержки.</p>';
  content+=rels.length?rels.map(r=>chapter('link-'+r.id,r.title,'relations',`<span class="eyebrow">${r.type==='colonial'?'КОЛОНИАЛЬНАЯ ЗАВИСИМОСТЬ':'ТОРГОВЛЯ И ОБМЕН'}</span><dl><dt>Что отправляли</dt><dd>${esc(r.goods)}</dd><dt>Встречный поток и контроль</dt><dd>${esc(r.returns)}</dd><dt>Выгоды и издержки</dt><dd>${esc(r.impact)}</dd></dl>${sourceLinks(r.sources)}<div class="relation-card"><button data-culture="${r.from===c.id?r.to:r.from}">Открыть другую сторону ${icon('arrow')}</button></div>`,open.has('link-'+r.id))).join(''):'<p class="uncertainty">Проверенные связи для этого года и фильтра ещё не добавлены. Другие типы связей можно найти через поиск.</p>';
  if(relationType!=='all')content+='<button class="secondary" id="allRelations">Показать все типы связей</button>';
 }
 content+=chapter('sources','Источники и оговорки','book',`<p>${esc(c.note)}</p>${sourceLinks(c.sources)}`,open.has('sources'));
 $('#detail').innerHTML=html(`<div class="detail-top"><span>${esc(c.region.toUpperCase())}</span><span class="type-label">${esc(c.kind)}</span></div><h2>${esc(c.name)}</h2><div class="period">${period(c)}</div>${content}<button class="primary" id="compare">${icon('globe')}Сравнить с современниками ${icon('arrow')}</button>${c.id==='egypt-old'&&year>=-3000&&year<=-1800?'<button class="secondary" data-compare="caral">А что в это время в Америке?</button>':''}`);
}
function modal(markup){modalSource=markup;stop();setSpin(false);toggleYear(false);toggleLegend(false);$('#modalContent').innerHTML=html(markup);if(!$('#modal').open)$('#modal').showModal();}
function about(){modal(`<h2>История людей и государств.</h2><p>Исследуйте общества, верования и связи в выбранном году. Карта объединяет датированные территории государств, отдельные культурные ареалы и региональные истории.</p><div class="stat-grid"><span><strong>${polityCatalog.length}</strong><small>государств и политических обществ</small></span><span><strong>${data.cultures.length}</strong><small>подробных историй</small></span><span><strong>30</strong><small>региональных обзоров</small></span></div><h3>Покрытие карты</h3><p>Для периода от 3400 года до н. э. до 2024 года используется Cliopatria: у каждого контура есть собственный интервал действия. Изменения доступны по году, но это приблизительная историческая реконструкция, а не ежегодная инструментальная съёмка. Для более раннего времени используются культурные срезы и региональные очерки. Для 2025 года отображается последний доступный контур 2024 года с явной датой.</p><h3>Что ещё неизвестно</h3><p>В наборе нет всех существовавших обществ. Незакрашенная территория не считается пустой: нажатие открывает региональный контекст. Он не доказывает заселение каждой точки. Религиозные ареалы остаются выборочными; религия правителя не принимается за веру всего населения. Общие сведения о государстве отделены от датированных фактов.</p><h3>Источники</h3><p>Cliopatria · Seshat Global History Databank · CC BY 4.0. Структурированные справки: Wikidata · CC0. Ранние карты: Historical Basemaps · GPL-3.0. География: Natural Earth, public domain. Тексты и ссылки приведены в отдельных карточках. Английская редакция подготовлена с локальным машинным переводом и терминологической правкой; спорные места требуют редакторской проверки.</p><div class="source-index"><a class="source-link" href="https://github.com/Seshat-Global-History-Databank/cliopatria" target="_blank" rel="noopener">Cliopatria · Seshat ↗</a><a class="source-link" href="data/cliopatria/LICENSE.txt" target="_blank" rel="noopener">Атрибуция и обработка геоданных ↗</a>${sourceLinks(Object.keys(data.sources))}</div>`);}

function showSources(){const c=data.cultures.find(c=>c.id===selected);if(!c)return;modal(`<h2>${esc(c.name)}<br>Источники и оговорки</h2><p>${esc(c.note)}</p><p>${period(c)}. Для точных событий и спорных интерпретаций сверяйтесь с первоисточниками. Карточка — краткий обзор, а не полная библиография.</p><div class="source-index">${sourceLinks(c.sources)}</div>`);}
function compare(aId=selected,bId){const cs=current(),a=cs.find(c=>c.id===aId)||cs[0],b=cs.find(c=>c.id===bId)||cs.find(c=>c.id!==a?.id);if(!a||!b){toast('Для сравнения нужны как минимум две записи в одном году.');return;}const opts=id=>cs.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('');modal(`<span class="eyebrow">ОДНОВРЕМЕННО НА ЗЕМЛЕ / ${formatYear(year)}</span><h2>Разные миры. Один год.</h2><div class="compare-chooser"><select id="compareA" aria-label="Первая культура">${opts(a.id)}</select><select id="compareB" aria-label="Вторая культура">${opts(b.id)}</select></div><div class="comparison">${[a,b].map(c=>`<article><h3>${esc(c.name)}</h3><span class="eyebrow">${esc(c.region)}</span><p>${esc(c.summary)}</p><span class="compare-label">УСТРОЙСТВО ОБЩЕСТВА</span><p>${esc(c.government)}. ${esc(c.society)}</p><span class="compare-label">ХОЗЯЙСТВО</span><p>${esc(c.economy)}</p><span class="compare-label">ВЕРОВАНИЯ</span><p>${c.religions.map(id=>esc(data.religions[id].name)).join(', ')}</p>${sourceLinks(c.sources)}<p>${esc(c.note)}</p></article>`).join('')}</div><p>Сосуществование во времени само по себе не доказывает контактов между обществами.</p>`);$('#compareA').onchange=()=>compare($('#compareA').value,$('#compareB').value);$('#compareB').onchange=()=>compare($('#compareA').value,$('#compareB').value);}
function journeys(){modal($('#journeyTemplate').innerHTML);}
function showEpochs(){let epoch=epochs[0];for(const e of epochs)if(year>=e.start)epoch=e;modal(`<span class="eyebrow">ВЫБЕРИТЕ ТОЧКУ ОТПРАВЛЕНИЯ</span><h2>У времени много глубин.</h2><p>Переходите от археологических эпох к конкретным годам. Периодизация условна и отличается в разных регионах.</p><div class="epoch-options">${epochs.map((e,i)=>`<button data-epoch="${e.year}" class="${epoch===e?'active':''}"><span class="epoch-index">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(e.name)}</strong><small>${formatYear(e.year)}</small></span></button>`).join('')}</div>`);}
function help(){modal(`<span class="eyebrow">НЕБОЛЬШОЙ КОМПАС ДЛЯ БОЛЬШОГО МИРА</span><h2>Исследуйте в своём ритме.</h2><div class="help-grid"><article class="help-item">${icon('globe')}<h3>Прикоснитесь к Земле</h3><p>Проведите одним пальцем, чтобы вращать планету. Разведите два пальца, чтобы приблизить. На компьютере используйте перетаскивание и колесо мыши.</p></article><article class="help-item">${icon('time')}<h3>Двигайтесь во времени</h3><p>Шкала внизу ведёт через эпохи. Нажмите на год, чтобы ввести свой, или на название эпохи, чтобы выбрать период. Кнопка воспроизведения запускает путешествие.</p></article><article class="help-item">${icon('cultures')}<h3>Следуйте за любопытством</h3><p>Нажмите на закрашенную область. Города и памятники можно дополнительно включить в легенде. Карточка открывается по запросу; разделы внутри раскрываются отдельно. В поиске культуры сгруппированы по частям света.</p></article><article class="help-item">${icon('compass')}<h3>Меняйте угол зрения</h3><p>Переключайте культуры, религии и связи. Путешествия предлагают готовые вопросы. Режим погружения скрывает управление; вернуть его можно кнопкой на экране или Escape.</p></article></div><p>Клавиатура: стрелки вращают глобус, + и − меняют масштаб. / открывает поиск, F — погружение, Escape — закрыть панель. Все действия также доступны кнопками.</p>`);}
function toggleYear(show){const active=typeof show==='boolean'?show:$('#yearPopover').hidden;$('#yearPopover').hidden=!active;$('#yearToggle').setAttribute('aria-expanded',String(active));if(active){toggleLegend(false);requestAnimationFrame(()=>{$('#yearInput').focus();$('#yearInput').select();});}}
function toggleLegend(show){const active=typeof show==='boolean'?show:$('#legendPanel').hidden;$('#legendPanel').hidden=!active;$('#legendToggle').setAttribute('aria-expanded',String(active));if(active){toggleYear(false);setPanel(null,false);}}
function clearFilters(){religionFilter='all';selectedArea=null;$('#religionFilter').value='all';q='';region='all';relationType='all';$('#search').value='';$('#region').value='all';$('#relationType').value='all';render();}
function story(name){stop();clearFilters();$('#modal').close();setPanel(null,false);if(name==='pyramids'){year=-2560;mode='cultures';selected='egypt-old';render();globe.focus([31,20]);compare('egypt-old','caral');}else if(name==='novgorod'){year=1250;mode='relations';selected='novgorod';render();globe.focus([24,52]);setPanel('detail');toast('1250 год. Откройте связь с ганзейскими купцами.');}else{year=1600;mode='relations';selected='potosi';render();globe.focus([-40,-3]);setPanel('detail');toast('1600 год. Откройте историю серебра и колониального контроля.');}}
function stop(){clearInterval(timer);timer=null;$('#play').innerHTML=html(icon('play'));$('#play').setAttribute('aria-label',tx('Запустить путешествие во времени'));$('#play').setAttribute('aria-pressed','false');}
function play(){if(timer){stop();return;}if(year>=MAX_YEAR)setYear(MIN_YEAR);$('#play').innerHTML=html(icon('pause'));$('#play').setAttribute('aria-label',tx('Остановить путешествие'));$('#play').setAttribute('aria-pressed','true');timer=setInterval(()=>{const p=Math.min(1000,yearToPosition(year)+4);setYear(positionToYear(p));if(p>=1000)stop();},500);}
function setSpin(active){globe?.setSpinning(active);$('#autoRotate').setAttribute('aria-pressed',String(active));$('#autoRotate').setAttribute('aria-label',tx(active?'Остановить плавное вращение':'Включить плавное вращение'));}
function changeLanguage(value){setLanguage(value);setMapLanguage(getLanguage()==='en'?'original':'ru');$('#languageSelect').value=getLanguage();$('#mapLanguage').value=getLanguage()==='en'?'original':'ru';try{localStorage.setItem('chronos-language',getLanguage());}catch{}translateShell();document.title=tx('Хронос — Земля. Человек. Время.');render();if($('#modal').open&&modalSource)$('#modalContent').innerHTML=html(modalSource);}
function bind(){document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.entity){pendingEntity=b.dataset.entity;stop();setYear(Number(b.dataset.year));}if(b.dataset.culture)selectCulture(b.dataset.culture);if(b.dataset.area){const a=displayAreas.find(f=>f.id===b.dataset.area);if(a)selectArea(a,true);}if(b.dataset.mode)setMode(b.dataset.mode);if(b.dataset.epoch){stop();$('#modal').close();setPanel(null,false);setYear(Number(b.dataset.epoch));const c=data.cultures.find(c=>c.id===selected);if(c)globe.focus(c.coordinates);$('#epochsToggle').focus({preventScroll:true});}if(b.dataset.story)story(b.dataset.story);if(b.dataset.compare)compare(selected,b.dataset.compare);if(b.hasAttribute('data-about'))about();if(b.hasAttribute('data-close-panel'))setPanel(null);if(b.hasAttribute('data-close-legend')){toggleLegend(false);$('#legendToggle').focus();}if(b.id==='clearFilters'||b.id==='resetFilters')clearFilters();if(b.id==='compare')compare();if(b.id==='selectedSources')showSources();if(b.id==='allRelations'){relationType='all';$('#relationType').value='all';render();}});
 $('#languageSelect').onchange=e=>changeLanguage(e.target.value);$('#mapLanguage').onchange=e=>{setMapLanguage(e.target.value);try{localStorage.setItem('chronos-map-language',e.target.value);}catch{}render();};$('#showPlaces').onchange=e=>{showPlaces=e.target.checked;applyAreas();};$('#religionFilter').onchange=e=>{religionFilter=e.target.value;selectedArea=null;syncAreas();persist();};$('#mapSlice').onclick=mapNotes;$('#mapMeaning').onclick=mapNotes;$('#prevSlice').onclick=()=>stepSlice(-1);$('#nextSlice').onclick=()=>stepSlice(1);
 $('#yearForm').addEventListener('submit',e=>{e.preventDefault();const y=parseYear($('#yearInput').value,$('#era').value);if(y===null){$('#yearError').textContent=tx(`Введите целый год без нуля: от 100 000 до н. э. до ${MAX_YEAR} н. э.`);return;}$('#yearError').textContent=tx('');stop();setYear(y);toggleYear(false);$('#dateJump').focus({preventScroll:true});});
 $('#timeRange').addEventListener('input',e=>{stop();$('#yearError').textContent=tx('');setYear(positionToYear(Number(e.target.value)));});
 $('#search').oninput=e=>{q=e.target.value;render();};$('#region').onchange=e=>{region=e.target.value;render();};$('#relationType').onchange=e=>{relationType=e.target.value;render();};
 $('#searchToggle').onclick=()=>{toggleLegend(false);toggleYear(false);setPanel(panel==='explorer'?null:'explorer');};$('#legendToggle').onclick=()=>toggleLegend();$('#dateJump').onclick=()=>toggleYear();$('#yearToggle').onclick=()=>toggleYear();$('#closeYear').onclick=()=>{toggleYear(false);$('#yearToggle').focus();};$('#epochsToggle').onclick=showEpochs;
 $('#resetView').onclick=()=>{setSpin(false);globe.reset();};$('#zoomIn').onclick=()=>globe.setZoom(globe.zoom*1.2);$('#zoomOut').onclick=()=>globe.setZoom(globe.zoom/1.2);$('#autoRotate').onclick=()=>setSpin(!globe.spinning);$('#focusMode').onclick=()=>setImmersive(!document.body.classList.contains('focus-mode'));$('#exitFocus').onclick=()=>setImmersive(false);$('#play').onclick=play;
 document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();setSpin(false);}});
 ['aboutNav','coverageBtn','methodNav'].forEach(id=>$('#'+id).onclick=about);$('#help').onclick=help;$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});$('#storiesNav').onclick=journeys;$('#journeyToggle').onclick=journeys;$('#atlasNav').onclick=()=>{setPanel(null);toggleYear(false);toggleLegend(false);};
 document.addEventListener('keydown',e=>{const editing=e.target.closest('input,select,textarea,[contenteditable="true"]');if(e.key==='Escape'&&!$('#modal').open){if(!$('#yearPopover').hidden){toggleYear(false);$('#yearToggle').focus();}else if(!$('#legendPanel').hidden){toggleLegend(false);$('#legendToggle').focus();}else if(panel)setPanel(null);else if(document.body.classList.contains('focus-mode'))setImmersive(false);}if(editing||$('#modal').open||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='/'){e.preventDefault();if(document.body.classList.contains('focus-mode'))setImmersive(false);setPanel('explorer');}if(e.key.toLowerCase()==='f'){e.preventDefault();setImmersive(!document.body.classList.contains('focus-mode'));}});
 $('#share').onclick=async()=>{persist();try{await navigator.clipboard.writeText(location.href);toast('Ссылка на этот момент скопирована.');}catch{modal(`<h2>Пригласите в этот момент.</h2><p>Скопируйте адрес выбранного года и режима:</p><input aria-label="Ссылка" class="share-input" readonly value="${esc(location.href)}">`);}};
}
function areaSources(f){if(f.properties.source==='cliopatria')return '<a class="source-link" href="https://github.com/Seshat-Global-History-Databank/cliopatria" target="_blank" rel="noopener">Cliopatria · Seshat Global History Databank · CC BY 4.0 ↗</a>';const src=f.properties.sources||[];if(src.length)return src.map(id=>{const s=editorial.sources[id];return s?`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`:'';}).join('');return '<a class="source-link" href="https://github.com/aourednik/historical-basemaps" target="_blank" rel="noopener">André Ourednik и участники · Historical Basemaps ↗</a>';}
function catalogRows(){if(!q)return '';const found=searchCatalog(polityCatalog,q,year,n=>areaName({properties:{name:n}},'ru'));return `<div class="list-heading"><span class="eyebrow">ГОСУДАРСТВА ВО ВСЕХ ЭПОХАХ</span><span>${found.length}</span></div>${found.map(e=>`<button class="culture-row" data-entity="${esc(e.id)}" data-year="${e.target}"><span><strong>${esc(areaName({properties:{name:e.name}}))}</strong><small>${e.periods.map(([a,b])=>formatYear(a)+' — '+formatYear(b)).join('; ')} · ${e.active?'в выбранном году':'перейти к '+formatYear(e.target)}</small></span>${icon('arrow')}</button>`).join('')}`;}
function areaRows(){const unique=new Map();for(const f of displayAreas)if(!unique.has(areaName(f)))unique.set(areaName(f),f);return [...unique.values()].sort((a,b)=>areaName(a).localeCompare(areaName(b),'ru')).map(f=>`<button class="culture-row" data-area="${esc(f.id)}"><span class="swatch" style="background:${areaColor(f)}"></span><span><strong>${esc(areaName(f))}</strong><small>${f.properties.mode==='religions'?'Религиозный ареал':f.properties.mode==='cultures'?'Культурный ареал':f.properties.background?'Региональная история людей':'Земли и общества'} · ${formatYear(f.properties.snapshot??territoryData?.year??year)}</small></span><span class="row-arrow">${icon('arrow')}</span></button>`).join('');}
function applyAreas(){globe.place=selectedArea?.properties.mode==='context'?selectedArea.properties.anchor:null;globe.setAreas(displayAreas,selectedArea?.id||null,showPlaces);$('#religionFilterLabel').hidden=mode!=='religions';const title=mode==='religions'?'РЕЛИГИОЗНЫЕ АРЕАЛЫ':'ТЕРРИТОРИИ НА КАРТЕ';$('#territoryResults')?.remove();const box=document.createElement('div');box.id='territoryResults';box.innerHTML=html(`<div class="list-heading"><span class="eyebrow">${title}</span><span>${displayAreas.length}</span></div>${catalogRows()}${areaRows()||'<p class="empty">Нажмите на сушу, чтобы открыть историю региона, даже если его границы не обозначены.</p>'}`);$('#cultureList').append(box);if(mode==='religions'){$('#legend').innerHTML=html([...new Map(displayAreas.flatMap(f=>f.properties.traditions||[{id:f.properties.religion,name:editorial.religions[f.properties.religion],color:f.properties.color}]).map(t=>[t.id,t])).values()].map(t=>`<span><i style="background:${t.color}"></i>${esc(t.name)}</span>`).join('')+'<span class="legend-pattern">Цветные полосы: сосуществование традиций, не доли населения</span>');}else $('#legend').innerHTML=html('<span><i style="background:#61c9c0"></i>Мягкая подсветка: региональная история людей</span><span>Яркие области и пунктир: государства и культурные ареалы</span><span>Пустое место в политическом слое не означает отсутствие людей</span>');}
async function syncAreas(){if(!territoryStore)return;const token=++areaRequest,y=year,m=mode;currentMapYear=null;$('#prevSlice').disabled=true;$('#nextSlice').disabled=true;$('#sliceYear').textContent=tx('Загружаем территориальный срез…');globe.setAreas([],null,showPlaces);try{let features,snapshot;if(m==='religions'){const d=religionFeatures(editorial,y,religionFilter,worldRegions,beliefs);snapshot=d.year;features=d.features;}else{const d=y>=polityManifest.from?await polityStore.load(y):{year:y,features:[]};if(token!==areaRequest)return;territoryData=d;snapshot=d?.year;features=[...landscapeFeatures(worldRegions,y),...territoryStore.cultureFeatures(d,y)];}if(token!==areaRequest||year!==y||mode!==m)return;currentMapYear=snapshot;displayAreas=features.map(f=>({...f,properties:{...f.properties,recordId:f.properties.mode==='religions'?null:/кельтские/i.test(f.properties.name)?'celts':cultureForArea(f,data.cultures,y)}})).filter(f=>!q||`${areaName(f)} ${areaName(f,'ru')} ${f.properties.name} ${f.properties.group||''}`.toLocaleLowerCase('ru').includes(q.trim().toLocaleLowerCase('ru'))||data.cultures.some(c=>c.id===f.properties.recordId&&matches(c,q)));
 $('#sliceYear').textContent=tx(snapshot===null||(m==='religions'&&!displayAreas.length)?'Нет ареалов для выбранного года / фильтра':`${m==='religions'?'Ареалы':'Общества и границы'}: срез ${formatYear(snapshot)}${snapshot!==y?' · ≈':''}`);$('#mapSlice').title=snapshot===null?'О покрытии территорий':`Выбран ${formatYear(y)}. Контуры выбраны по интервалам действия в историческом наборе; точность реконструкции различается по регионам.`;const years=m==='religions'?editorial.snapshots:[...territoryManifest.snapshots.filter(s=>s.year<polityManifest.from).map(s=>s.year),...polityManifest.changes];$('#prevSlice').disabled=!years.some(v=>v<snapshot&&v>=MIN_YEAR);$('#nextSlice').disabled=!years.some(v=>v>snapshot&&v<=MAX_YEAR);if(pendingAreaId){const place=/^place:(-?\d+(?:\.\d+)?):(-?\d+(?:\.\d+)?)$/.exec(pendingAreaId);selectedArea=place?placeFeature([+place[1],+place[2]]):displayAreas.find(f=>f.id===pendingAreaId)||null;pendingAreaId=null;if(selectedArea){if(place)selected=null;setPanel('detail',false);renderAreaDetail();persist();}}applyAreas();if(selectedArea)renderAreaDetail();if(pendingEntity){const id=pendingEntity;pendingEntity=null;const f=displayAreas.find(f=>f.properties.entity===id);if(f)selectArea(f,true);}}catch(err){if(token!==areaRequest)return;displayAreas=[];currentMapYear=null;$('#sliceYear').textContent=tx('Срез не загрузился · повторить');applyAreas();console.error(err);}}
function selectArea(f,focus=false){stop();setSpin(false);if(f.properties.recordId&&mode!=='religions'){selectCulture(f.properties.recordId,focus);return;}selectedArea=f;renderAreaDetail();globe.place=f.properties.mode==='context'?f.properties.anchor:null;globe.setAreas(displayAreas,f.id,showPlaces);setPanel('detail');toggleYear(false);toggleLegend(false);if(focus)globe.focus(f.properties.anchor||d3.geoCentroid(f));persist();}
function placeFeature(coords){if(!Array.isArray(coords)||coords.length!==2||!coords.every(Number.isFinite)||Math.abs(coords[0])>180||Math.abs(coords[1])>90)return null;const c=contextAt(coords,year);return {type:'Feature',id:'place:'+coords.map(v=>v.toFixed(3)).join(':'),properties:{name:c.region,title:c.region,mode:'context',anchor:coords},geometry:{type:'Point',coordinates:coords}};}
function selectPlace(coords){const f=placeFeature(coords);if(!f)return;selected=null;selectArea(f);}
function renderAreaDetail(){const f=selectedArea;if(!f)return;const p=f.properties,coords=p.anchor||d3.geoCentroid(f),c=contextAt(coords,year),isPlace=p.mode==='context',isReligion=p.mode==='religions';const profile=polityProfiles[p.wikidata],locale=getLanguage(),facts=narrativeForArea(f,year,profile,c,locale);const r=isReligion&&!p.traditions?data.religions[p.religion==='eastern-christianity'?'christianity':p.religion]:null;
 const local=current().filter(item=>regionAt(item.coordinates).id===c.id&&!['un-world','decolon'].includes(item.id));
 const entitySources=(p.traditions?[...new Map(p.traditions.flatMap(t=>t.sources).map(s=>[s.url,s])).values()]:(facts.sources||[])).map(s=>`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`).join('');
 const kind=isPlace?'ИСТОРИЯ МЕСТА':isReligion?'РЕЛИГИИ И ВЕРОВАНИЯ':p.mode==='cultures'?'КУЛЬТУРЫ И ОБЩЕСТВА':'ЗЕМЛИ И НАРОДЫ';
 const profileFacts=factsForYear(profile,year).filter(f=>!(p.wikidata==='Q178665'&&f.property==='P36'));const heading=isPlace?c.region:areaName(f),scope=isReligion?(p.traditions?'Традиции региона':'Религиозная традиция'):facts.scope;
 const summary=p.traditions?p.summary:(r?.summary||facts.summary);let content=summary?`<p class="summary">${esc(summary)}</p>`:'';
 if(isReligion&&p.traditions){content+=chapter('traditions','Традиции и практики региона','religions',p.traditions.map(t=>`<article class="tradition-entry"><h3><i style="background:${esc(t.color)}"></i>${esc(t.name)}</h3><p class="context-note">${esc(t.origin)}</p><p>${esc(t.summary)}</p></article>`).join(''),true);content+=`<p class="context-note">${esc(p.note)}</p>`;}
 else if(isReligion&&r){content+=chapter('origin','Возникновение и особенности','religions',`<p>${esc(r.origin)}</p><p>${p.basis==='mixed'?'На этой территории сосуществовали разные общины и традиции.':p.basis==='institutional'?'Здесь действовали религиозные институты и общины. Это не означает, что к традиции принадлежало большинство жителей.':'В этом региональном ареале традиция имела значительное распространение. Локальная религиозная жизнь могла быть разнообразнее.'}</p>`,true);}
 else {if(profileFacts.length)content+=chapter('profile','Устройство государства','cultures',`<dl>${profileFacts.map(f=>`<dt>${esc(f.title[locale])}${f.scope==='general'?' · общий профиль':''}</dt><dd>${esc(f.value[locale]||f.value.en)}${f.scope==='dated'?` <small>(${f.from?formatYear(f.from):'…'} — ${f.to?formatYear(f.to):'…'})</small>`:''}</dd>`).join('')}</dl>`,true);if(p.areaKm2)content+=`<p class="area-measure">Площадь территории: ≈ ${Math.round(p.areaKm2).toLocaleString(locale==='en'?'en-US':'ru-RU')} км²</p>`;if(facts.society)content+=chapter('life','Люди и образ жизни','cultures',`<p>${esc(facts.society)}</p>`,true);if(facts.economy)content+=chapter('economy','Хозяйство и обмен','relations',`<p>${esc(facts.economy)}</p>`);if(facts.beliefs)content+=chapter('beliefs','Верования и ритуалы','religions',`<p>${esc(facts.beliefs)}</p>`);if(!isPlace&&profile?.description?.[locale]&&!facts.names)content+='<p class="context-note">Краткая характеристика относится к обществу в целом. Сведения с установленными датами отмечены отдельно.</p>';}
 if(!isPlace&&!isReligion)content+=chapter('surroundings','Географическое окружение','compass',`<p class="context-note">Отдельный обзор региона «${esc(c.region)}». Он не является описанием выбранного государства или его населения.</p><p>${esc(c.summary)}</p>${c.sources.map(s=>`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`).join('')}`);
 if(local.length)content+=chapter('stories','Культуры и общества этого региона','compass',`<p class="context-note">Другие истории региона в выбранном году. Они не обязательно относятся к этой точке.</p>${local.map(item=>`<button class="related-place" data-culture="${esc(item.id)}"><span>${esc(item.name)}</span>${icon('arrow')}</button>`).join('')}`);
 content+=chapter('sources','Источники и точность','book',`${profile?`<a class="source-link" href="${esc(profile.source)}" target="_blank" rel="noopener">Wikidata · CC0</a>`:''}${entitySources}${isPlace||p.traditions?'':areaSources(f)}${isPlace?`<p>Обзор относится к региону «${esc(c.region)}». Он не подтверждает заселение каждой точки или однородность населения.</p>`:''}${isPlace||p.traditions?'':`<p>Дата контура: ${p.source==='cliopatria'?`${formatYear(p.from)} — ${formatYear(p.to)}`:formatYear(p.snapshot??territoryData?.year??year)}. ${esc(p.note||'Контур приблизителен; между срезами точное положение границы не восстановлено.')}</p>${nameIsTranscribed(f)?`<p>Самоназвание передано кириллицей: ${esc(p.name)}. Это рабочая передача, а не утверждённый русский этноним.</p>`:''}`}`);
 $('#detail').innerHTML=html(`<div class="detail-top">${kind}</div><h2>${esc(heading)}</h2><div class="period">${formatYear(year)}${isPlace?' · '+Math.abs(coords[1]).toFixed(1)+'° '+(coords[1]>=0?'с. ш.':'ю. ш.')+', '+Math.abs(coords[0]).toFixed(1)+'° '+(coords[0]>=0?'в. д.':'з. д.') :''}</div><div class="context-badge">${scope}${isReligion?'':' · '+esc(c.region)}</div>${isPlace?`<p class="settlement-status">${esc(c.status)}</p>`:''}${content}`);
}

function stepSlice(direction){const years=mode==='religions'?editorial.snapshots:[...territoryManifest.snapshots.filter(s=>s.year<polityManifest.from).map(s=>s.year),...polityManifest.changes];const target=direction>0?years.find(v=>v>currentMapYear&&v<=MAX_YEAR):years.filter(v=>v<currentMapYear&&v>=MIN_YEAR).at(-1);if(target!==undefined){stop();setYear(target);}}
function mapNotes(){if(currentMapYear===null){mapPromise=syncAreas();return;}modal(`<span class="eyebrow">ПРОСТРАНСТВО И ВРЕМЯ</span><h2>Люди, общества, государства.</h2><p>Мягкая бирюзовая подсветка открывает истории географических регионов с известными свидетельствами присутствия людей. Она сохраняется и после возникновения государств. Это не карта плотности населения или сплошного заселения каждой точки.</p><p>Яркие политические области показаны поверх региональных историй. Отсутствие государства в наборе не означает отсутствия жителей, хозяйства, культуры или правил землепользования.</p><p>Религиозные полосы показывают совместное присутствие разных традиций, а не проценты последователей. Анимизм и тотемические связи — сравнительные понятия и практики, не единая мировая религия. Они не приписываются автоматически всем доисторическим людям.</p><p>На временной шкале выбран ${formatYear(year)}. Территориальный слой показывает ${formatYear(currentMapYear)}.</p><p>Политические контуры Cliopatria выбираются по собственным интервалам действия. Кнопки рядом с годом карты переходят к следующему или предыдущему изменению в наборе. Это приблизительные реконструкции; отсутствие изменения в наборе не доказывает неизменность границы на местности.</p><p>До 3400 года до н. э. показаны региональные истории; прежние огромные контуры видов древних людей исключены из основного слоя. Истории регионов не являются картой точного расселения, культурных или этнических границ.</p><p>Религиозный слой независим от границ государств. Заливка предполагаемого преобладания, смешанные зоны и распространение институтов различаются. Религия правителя не заменяет данные о верованиях населения.</p><div class="source-index"><a class="source-link" href="https://github.com/Seshat-Global-History-Databank/cliopatria" target="_blank" rel="noopener">Cliopatria · Seshat · CC BY 4.0 ↗</a><a class="source-link" href="https://github.com/aourednik/historical-basemaps" target="_blank" rel="noopener">Historical Basemaps · GPL-3.0 ↗</a><a class="source-link" href="data/cliopatria/LICENSE.txt" target="_blank" rel="noopener">Атрибуция и обработка геоданных ↗</a></div>`);}


async function init(){try{const [d,l,manifest,areas,clio,catalog,profiles,translations,readingRegions]=await Promise.all([fetch('data/history.json').then(r=>{if(!r.ok)throw Error('Историческая база недоступна');return r.json();}),fetch('data/land.geojson').then(r=>{if(!r.ok)throw Error('География недоступна');return r.json();}),fetch('data/territories/index.json').then(r=>{if(!r.ok)throw Error('Индекс территорий недоступен');return r.json();}),fetch('data/editorial-areas.geojson').then(r=>{if(!r.ok)throw Error('Ареалы недоступны');return r.json();}),fetch('data/cliopatria/index.json').then(r=>r.json()),fetch('data/cliopatria/catalog.json').then(r=>r.json()),fetch('data/cliopatria/profiles.json').then(r=>r.json()),fetch('locales/en.json').then(r=>r.json()),fetch('data/reading-regions.geojson').then(r=>r.json())]);if(!window.d3)throw Error('Не удалось загрузить библиотеку глобуса');configureTranslations(translations);let language=new URLSearchParams(location.hash.slice(1)).get('lang');try{language ||= localStorage.getItem('chronos-language');}catch{}setLanguage(language||'ru');setMapLanguage(getLanguage()==='en'?'original':'ru');$('#languageSelect').value=getLanguage();$('#mapLanguage').value=getLanguage()==='en'?'original':'ru';translateShell();document.title=tx('Хронос — Земля. Человек. Время.');worldRegions=readingRegions;beliefs=beliefCatalog(d);polityManifest=clio;polityCatalog=catalog;polityProfiles=profiles.entities;polityStore=new PolityStore(clio);data=d;territoryManifest=manifest;editorial=areas;editorial.features=editorial.features.map(f=>({...f,geometry:normalizeGeometry(f.geometry,d3.geoArea)}));territoryStore=new TerritoryStore(manifest,editorial);$('#religionFilter').innerHTML=html('<option value="all">Все традиции и практики</option>'+Object.entries({...Object.fromEntries(Object.entries(beliefs).map(([id,p])=>[id,p.name])),...editorial.religions,...beliefFacets}).map(([id,title])=>`<option value="${id}">${esc(title)}</option>`).join(''));const params=new URLSearchParams(location.hash.slice(1));pendingAreaId=params.get('area');if(params.get('religion') in {...beliefs,...editorial.religions,...beliefFacets}){religionFilter=params.get('religion');$('#religionFilter').value=religionFilter;}let saved=null;try{saved=JSON.parse(localStorage.getItem('chronos-state-v1'));}catch{}const raw=params.has('year')?Number(params.get('year')):saved?.year;if(Number.isInteger(raw)&&raw!==0&&raw>=MIN_YEAR&&raw<=MAX_YEAR)year=raw;const m=params.get('mode')||saved?.mode;if(['cultures','religions','relations'].includes(m))mode=m;const s=params.get('culture')||saved?.selected;if(data.cultures.some(c=>c.id===s))selected=s;if(!current().some(c=>c.id===selected))selected=chooseCurrent();
 globe=new Globe($('#globe'),l,id=>selectCulture(id,false));globe.showPoints=false;globe.onAreaSelect=selectArea;globe.onPlaceSelect=selectPlace;globe.onEmpty=()=>{setPanel(null,false);toggleYear(false);toggleLegend(false);};globe.onInteract=()=>{$('#autoRotate').setAttribute('aria-pressed','false');$('#autoRotate').setAttribute('aria-label',tx('Включить плавное вращение'));};$('#loading').hidden=true;
 const ticks=[-100000,-12000,-4000,-1000,1,1000,1800,2025];$('#ticks').innerHTML=html(ticks.map(y=>`<span style="left:${yearToPosition(y)/10}%">${y<0?'−':''}${Math.abs(y).toLocaleString(getLanguage()==='en'?'en-US':'ru-RU')}</span>`).join(''));bind();setPanel(null,false);render();
 }catch(err){$('#loading').innerHTML=html('Не удалось проявить карту. <button id="retryLoad">Попробовать ещё раз</button>');$('#loading').style.pointerEvents='auto';$('#retryLoad').onclick=()=>location.reload();console.error(err);toast(err.message);}}
export const appReady=init();
export async function whenReady(){await appReady;let pending;do{pending=mapPromise;await pending;}while(pending!==mapPromise);}
